#!/data/service/hnp/bin/bash
set -euo pipefail

binary="$1"
workdir="$2"
home="$workdir/home"
audio="$workdir/test.wav"

mkdir -p "$home" "$workdir"
test -x "$binary" || exit 1
printf 'default_driver=null\n' > "$home/.libao"
test -f "$home/.libao" || exit 1
printf '%s' '' | base64 -d > "$audio"
test -s "$audio" || exit 1

HOME="$home" TERM=xterm "$binary" -q -e 0.1 "$audio"
